import * as THREE from 'three';

/**
 * Client side of the humanoid point cloud generated by scripts/build-humanoid.mjs.
 * Points are split per body part and attached to a joint hierarchy so stages can
 * pose the figure (head turn, reach). Each part renders twice:
 *   1. an occluder pass (large depth-only splats) so hidden dots are culled,
 *   2. the visible dot pass with lighting, rim, highlight and scan effects.
 */

export const PART = {
  head: 0,
  neck: 1,
  torso: 2,
  pelvis: 3,
  upperArmR: 4,
  forearmR: 5,
  handR: 6,
  upperArmL: 7,
  forearmL: 8,
  handL: 9,
  thighR: 10,
  shinR: 11,
  footR: 12,
  thighL: 13,
  shinL: 14,
  footL: 15,
} as const;
const PART_COUNT = 16;

/** Nested blue-noise level boundaries written by the generator (public/models/humanoid-levels.json). */
export const HUMANOID_LEVELS = [12022, 20009, 32038, 51909, 96157];
/** Largest level boundary that does not exceed the requested budget. */
export function snapBudget(budget: number) {
  let pick = HUMANOID_LEVELS[0];
  for (const b of HUMANOID_LEVELS) if (b <= budget * 1.15) pick = b;
  return pick;
}

/** Joint pivots in the rest pose (must match the generator). */
const PIVOT: [number, number, number][] = [
  [0, 1.565, 0], // head
  [0, 1.49, 0], // neck
  [0, 1.05, 0], // torso (spine)
  [0, 0.95, 0], // pelvis
  [0.2, 1.4, 0], // upperArmR (shoulder)
  [0.252, 1.15, -0.006], // forearmR (elbow)
  [0.29, 0.886, 0.02], // handR (wrist)
  [-0.2, 1.4, 0],
  [-0.252, 1.15, -0.006],
  [-0.29, 0.886, 0.02],
  [0.1, 0.9, 0], // thighR (hip)
  [0.105, 0.505, 0.003], // shinR (knee)
  [0.103, 0.095, -0.012], // footR (ankle)
  [-0.1, 0.9, 0],
  [-0.105, 0.505, 0.003],
  [-0.103, 0.095, -0.012],
];
/** Parent of each part (−1 = root). */
const PARENT = [1, 2, 3, -1, 2, 4, 5, 2, 7, 8, 3, 10, 11, 3, 13, 14];

const dotVertex = /* glsl */ `
  attribute float aAccent;
  uniform float uSize;
  uniform float uPixelRatio;
  uniform float uOccluder;
  varying float vShade;
  varying float vAccent;
  varying float vRim;
  varying float vY;
  varying float vFacing;
  void main() {
    vec4 world = modelMatrix * vec4(position, 1.0);
    vec4 mv = viewMatrix * world;
    vec3 n = normalize(normalMatrix * normal);
    vec3 v = normalize(-mv.xyz);
    float facing = dot(n, v);
    vFacing = facing;
    vec3 L = normalize(vec3(0.35, 0.65, 0.68));
    vec3 L2 = normalize(vec3(-0.7, 0.1, -0.2));
    vShade = 0.2 + 0.95 * max(dot(n, L), 0.0) + 0.14 * max(dot(n, L2), 0.0);
    vRim = pow(1.0 - max(facing, 0.0), 2.2);
    vAccent = aAccent;
    vY = world.y;
    if (uOccluder > 0.5) {
      // Depth-only splat, pushed slightly back so front-facing dots win the depth test.
      mv.xyz *= 1.0 + 0.006;
      gl_Position = projectionMatrix * mv;
      gl_PointSize = uSize * 2.6 * uPixelRatio / -mv.z;
      return;
    }
    gl_Position = projectionMatrix * mv;
    gl_PointSize = max(1.0, uSize * uPixelRatio / -mv.z);
    if (facing < -0.15) gl_Position = vec4(2.0, 2.0, 2.0, 1.0);
  }
`;

const dotFragment = /* glsl */ `
  uniform float uOccluder;
  uniform vec3 uBase;
  uniform vec3 uCool;
  uniform vec3 uHighlightColor;
  uniform float uHighlight;
  uniform float uScan;
  uniform float uScanY;
  uniform float uDim;
  varying float vShade;
  varying float vAccent;
  varying float vRim;
  varying float vY;
  varying float vFacing;
  void main() {
    vec2 c = gl_PointCoord - 0.5;
    float r = length(c);
    if (r > 0.5) discard;
    if (uOccluder > 0.5) { gl_FragColor = vec4(0.0); return; }
    float dotMask = smoothstep(0.5, 0.36, r);
    vec3 col = uBase * vShade + uCool * vRim * 0.4;
    col = mix(col, uHighlightColor * (0.7 + 0.6 * vShade), uHighlight * 0.75);
    col += uHighlightColor * vAccent * 1.3;
    float scan = smoothstep(0.03, 0.0, abs(vY - uScanY)) * uScan;
    col += uHighlightColor * scan * 1.2;
    float alpha = dotMask * clamp(0.45 + vFacing * 0.9, 0.0, 1.0);
    gl_FragColor = vec4(col * uDim, alpha);
  }
`;

export type PointHumanoid = {
  root: THREE.Group;
  joints: THREE.Group[];
  materials: THREE.ShaderMaterial[];
  occluderMat: THREE.ShaderMaterial;
  count: number;
  dispose: () => void;
};

let cache: Promise<ArrayBuffer> | null = null;
export function loadHumanoidBuffer() {
  cache ??= fetch('/models/humanoid-points.bin').then((r) => {
    if (!r.ok) throw new Error(`humanoid model: HTTP ${r.status}`);
    return r.arrayBuffer();
  });
  return cache;
}

/** Decode the packed buffer into flat arrays (used by other scenes too). */
export function decodeHumanoid(buf: ArrayBuffer, budget: number) {
  const dv = new DataView(buf);
  const total = dv.getUint32(0, true);
  const n = Math.min(total, budget);
  const pos = new Float32Array(n * 3);
  const nor = new Float32Array(n * 3);
  const part = new Uint8Array(n);
  const accent = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    const o = 4 + i * 12;
    pos[i * 3] = dv.getInt16(o, true) / 16000;
    pos[i * 3 + 1] = dv.getInt16(o + 2, true) / 16000;
    pos[i * 3 + 2] = dv.getInt16(o + 4, true) / 16000;
    nor[i * 3] = dv.getInt8(o + 6) / 127;
    nor[i * 3 + 1] = dv.getInt8(o + 7) / 127;
    nor[i * 3 + 2] = dv.getInt8(o + 8) / 127;
    part[i] = dv.getUint8(o + 9);
    accent[i] = dv.getUint8(o + 10) / 255;
  }
  return { n, pos, nor, part, accent };
}

export function buildPointHumanoid(buf: ArrayBuffer, budget: number, dotSize: number): PointHumanoid {
  const { n, pos, nor, part, accent } = decodeHumanoid(buf, budget);

  // Joint hierarchy
  const root = new THREE.Group();
  const joints: THREE.Group[] = [];
  for (let i = 0; i < PART_COUNT; i++) joints.push(new THREE.Group());
  for (let i = 0; i < PART_COUNT; i++) {
    const p = PARENT[i];
    const pv = PIVOT[i];
    if (p < 0) {
      joints[i].position.set(...pv);
      root.add(joints[i]);
    } else {
      const pp = PIVOT[p];
      joints[i].position.set(pv[0] - pp[0], pv[1] - pp[1], pv[2] - pp[2]);
      joints[p].add(joints[i]);
    }
  }

  const counts = new Array(PART_COUNT).fill(0);
  for (let i = 0; i < n; i++) counts[part[i]]++;
  const occluderMat = new THREE.ShaderMaterial({
    vertexShader: dotVertex,
    fragmentShader: dotFragment,
    uniforms: { uSize: { value: dotSize }, uPixelRatio: { value: 1 }, uOccluder: { value: 1 } },
    colorWrite: false,
    depthWrite: true,
  });
  const materials: THREE.ShaderMaterial[] = [];
  const geometries: THREE.BufferGeometry[] = [];

  for (let p = 0; p < PART_COUNT; p++) {
    const m = counts[p];
    const gp = new Float32Array(m * 3);
    const gn = new Float32Array(m * 3);
    const ga = new Float32Array(m);
    const pv = PIVOT[p];
    let k = 0;
    for (let i = 0; i < n; i++) {
      if (part[i] !== p) continue;
      gp[k * 3] = pos[i * 3] - pv[0];
      gp[k * 3 + 1] = pos[i * 3 + 1] - pv[1];
      gp[k * 3 + 2] = pos[i * 3 + 2] - pv[2];
      gn.set([nor[i * 3], nor[i * 3 + 1], nor[i * 3 + 2]], k * 3);
      ga[k] = accent[i];
      k++;
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(gp, 3));
    g.setAttribute('normal', new THREE.BufferAttribute(gn, 3));
    g.setAttribute('aAccent', new THREE.BufferAttribute(ga, 1));
    g.computeBoundingSphere();
    geometries.push(g);

    const mat = new THREE.ShaderMaterial({
      vertexShader: dotVertex,
      fragmentShader: dotFragment,
      transparent: true,
      depthWrite: false,
      uniforms: {
        uSize: { value: dotSize },
        uPixelRatio: { value: 1 },
        uOccluder: { value: 0 },
        uBase: { value: new THREE.Color('#e9eef7') },
        uCool: { value: new THREE.Color('#9cc8ff') },
        uHighlightColor: { value: new THREE.Color('#3cc4d2') },
        uHighlight: { value: 0 },
        uScan: { value: 0 },
        uScanY: { value: 0 },
        uDim: { value: 1 },
      },
    });
    materials.push(mat);

    const occ = new THREE.Points(g, occluderMat);
    occ.renderOrder = -1;
    const dots = new THREE.Points(g, mat);
    dots.renderOrder = 1;
    joints[p].add(occ, dots);
  }

  return {
    root,
    joints,
    materials,
    occluderMat,
    count: n,
    dispose: () => {
      geometries.forEach((g) => g.dispose());
      materials.forEach((m) => m.dispose());
      occluderMat.dispose();
    },
  };
}

/** Pose: rest (0) → reach (1) with the right arm; subtle idle motion. */
export function poseHumanoid(h: PointHumanoid, reach: number, t: number, motion: number) {
  const J = h.joints;
  const breathe = Math.sin(t * 1.3) * 0.006 * motion;
  J[PART.torso].rotation.set(breathe + reach * 0.06, -reach * 0.1, 0);
  // reach out to the side and slightly forward — the work shelf sits beside the body
  J[PART.upperArmR].rotation.set(-reach * 0.55, 0, reach * 0.62);
  J[PART.forearmR].rotation.set(-reach * 0.75, 0, reach * 0.15);
  J[PART.handR].rotation.set(-reach * 0.15, reach * 0.4, 0);
  J[PART.upperArmL].rotation.set(Math.sin(t * 0.6) * 0.012 * motion, 0, 0);
}
